# ── Library API ───────────────────────────────────────────────────


def library_add_papers(
    paper_ids: list[str],
    titles: dict[str, str] | None = None,
    dois: dict[str, str] | None = None,
    source_file: str | None = None,
) -> dict:
    """Add papers to the personal library."""
    client = _get_client()

    # Build items from paper_ids
    items: list[dict[str, Any]] = []
    for pid in paper_ids:
        item: dict[str, Any] = {"paper_id": pid}
        if titles and pid in titles:
            item["title"] = titles[pid]
        if dois and pid in dois:
            item["doi"] = dois[pid]
        if source_file:
            item["import_source"] = f"cli_{source_file}"
        items.append(item)

    result = client.library.add_papers(items)
    return {
        "added": result.get("added", []),
        "total": result.get("total", 0),
    }


def library_update_metadata(paper_ids: list[str], metadata: dict[str, dict]) -> None:
    """Update metadata for library papers."""
    client = _get_client()
    for pid in paper_ids:
        if pid in metadata:
            try:
                client.library.update_paper(pid, metadata[pid])
            except Exception as e:
                logger.debug("Failed to update paper %s: %s", pid, e)


def library_get_papers() -> dict[str, dict]:
    """Get all papers from the personal library."""
    client = _get_client()
    try:
        result = client.library.list_papers()
        papers = result.get("papers", [])
        return {
            p.get("id", p.get("paper_id", "")): {
                "title": p.get("title", ""),
                "authors": p.get("authors", ""),
                "year": p.get("year"),
                "journal": p.get("journal"),
                "doi": p.get("doi"),
                "cited_by_count": p.get("cited_by_count"),
                "s2_id": p.get("s2_id"),
                "entry_type": p.get("entry_type"),
                "source_key": p.get("source_key"),
                "created_at": p.get("created_at"),
            }
            for p in papers
        }
    except Exception as e:
        logger.debug("library_get_papers failed: %s", e)
        return {}


def library_get_corpus_ids() -> list[str]:
    """Get list of corpus paper IDs from library."""
    client = _get_client()
    try:
        result = client.library.list_papers()
        papers = result.get("papers", [])
        return [p.get("paper_id") for p in papers if p.get("paper_id")]
    except Exception as e:
        logger.debug("library_get_corpus_ids failed: %s", e)
        return []


def library_get_info() -> dict | None:
    """Get info about the personal library."""
    client = _get_client()
    try:
        result = client.library.list_papers()
        papers = result.get("papers", [])
        total = len(papers)
        corpus = len([p for p in papers if p.get("paper_id")])
        custom = len([p for p in papers if p.get("custom_paper_id")])
        # Build papers dict keyed by paper ID
        papers_dict = {}
        for p in papers:
            pid = p.get("paper_id") or p.get("custom_paper_id") or p.get("id")
            if pid:
                papers_dict[str(pid)] = p

        return {
            "total": total,
            "matched": corpus,
            "unmatched": custom,
            "papers": papers_dict,
        }
    except Exception as e:
        logger.debug("library_get_info failed: %s", e)
        return None


def library_remove_papers(paper_ids: list[str]) -> int:
    """Remove papers from the personal library."""
    client = _get_client()
    count = 0
    for pid in paper_ids:
        try:
            response = client.library.list_papers(search=pid, per_page=200)
            entry = next(
                (
                    paper
                    for paper in response.get("papers", [])
                    if paper.get("paper_id") == pid
                ),
                None,
            )
            if not entry or not entry.get("id"):
                continue
            client.library.delete_paper(str(entry["id"]))
            count += 1
        except Exception as e:
            logger.debug("Failed to delete paper %s: %s", pid, e)
    return count
